import{_ as t}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as o,o as l,j as i,G as a,ae as r,a as n}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Medal of Sacrifice Act of 2025","description":"","frontmatter":{"legisId":"2026-05-28-medal-of-sacrifice-act-of-2025","title":"Medal of Sacrifice Act of 2025","displayTitle":"Medal of Sacrifice Act of 2025","lawNumber":"119-94","billNumber":"H.R. 3497","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ94.xml","publishDate":"2026-05-28T00:00:00-05:00","industries":["law-enforcement","government-operations"],"agencies":["Medal of Sacrifice Commission"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Medal of Sacrifice Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-28-medal-of-sacrifice-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Medal of Sacrifice Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-28-medal-of-sacrifice-act-of-2025\\",\\"datePublished\\":\\"2026-05-28T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-28-medal-of-sacrifice-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-05-28-medal-of-sacrifice-act-of-2025.md","filePath":"congress-bills/2026-05-28-medal-of-sacrifice-act-of-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-05-28-medal-of-sacrifice-act-of-2025.md"},u=Object.assign(d,{setup(c){return(f,e)=>(l(),o("div",null,[e[0]||(e[0]=i("h1",{id:"medal-of-sacrifice-act-of-2025",tabindex:"-1"},[n("Medal of Sacrifice Act of 2025 "),i("a",{class:"header-anchor",href:"#medal-of-sacrifice-act-of-2025","aria-label":'Permalink to "Medal of Sacrifice Act of 2025"'},"​")],-1)),a(t),a(s,{list:"/congress-bills"}),e[1]||(e[1]=r('<p>Signed into law on Thursday, May 28, 2026. Public Law 119-94, H.R. 3497.</p><p><strong>Headline:</strong> The law creates a presidential medal honoring law enforcement officers and first responders killed in the line of duty.</p><p><strong>Why it matters:</strong> It establishes a national form of recognition while creating a process to resolve disputed eligibility cases.</p><p><strong>What the law does:</strong></p><ul><li>Creates the presidential Medal of Sacrifice for eligible local, state, Tribal, territorial, and federal personnel.</li><li>Requires the President to appoint a 12-member unpaid commission within 150 days.</li><li>Directs the commission to advise on the medal’s design and eligibility rules, determine presentation procedures, and decide disputed cases.</li><li>Generally excludes people found to have acted outside their duties or against agency policies, unless the commission decides otherwise after an investigation.</li><li>Sets five-year commission terms and a two-term limit.</li><li>Requires the first medals to honor Deputies Ralph “Butch” Waller, Ignacio “Dan” Diaz, and Luis Paez.</li><li>Specifies the medal’s design, materials, and engraving.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Law enforcement officers and first responders killed in the line of duty.</li><li>Families and agencies of eligible fallen officers and responders.</li><li>Law enforcement, first responder, and knowledgeable organizations represented on the commission.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Families of eligible fallen officers and responders may receive presidential recognition of their sacrifice.</li><li>The public gets a formal national process for honoring line-of-duty deaths and reviewing disputed cases.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="medal-of-sacrifice-act-of-2025-1" tabindex="-1">Medal of Sacrifice Act of 2025 <a class="header-anchor" href="#medal-of-sacrifice-act-of-2025-1" aria-label="Permalink to &quot;Medal of Sacrifice Act of 2025&quot;">​</a></h3><p>This law creates a presidential Medal of Sacrifice for law enforcement officers and first responders killed in the line of duty. It establishes a commission to oversee the medal’s design, presentation, and eligibility decisions, including cases involving official findings of wrongdoing.</p><p><strong>Key takeaways:</strong></p><ul><li>Local, state, Tribal, territorial, and federal law enforcement officers and first responders killed in the line of duty are eligible for the medal.</li><li>An officer or responder found to have acted outside their duties or against agency policies is not eligible unless the commission determines otherwise after investigating the death.</li><li>The President must appoint a 12-member unpaid commission within 150 days, with members drawn from law enforcement, first responders, and knowledgeable organizations.</li><li>Commission members serve five-year terms and may serve no more than two terms.</li><li>The commission will advise on the medal’s design and eligibility criteria, decide how it is presented, and make final eligibility decisions in disputed cases.</li><li>The law directs the commission to make the first awards to Deputies Ralph “Butch” Waller, Ignacio “Dan” Diaz, and Luis Paez, and specifies the medal’s design, materials, and engraving.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ94.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ94.xml</a></p>',15))]))}});export{h as __pageData,u as default};
